fn argmin(a: Vec<i8>) -> usize {
    // Since the array is non-empty, initialize min_index to 0 (first element)
    let mut min_index = 0;
    let mut min_value = a[0];

    // Iterate over the array starting from index 1
    for i in 1..a.len() {
        // If we find a strictly smaller value, update min_index and min_value
        if a[i] < min_value {
            min_index = i;
            min_value = a[i];
        }
    }

    // min_index now holds the index of the first occurrence of the smallest value
    min_index
}